import java.util.Arrays;
public class Check {
  static void eq(int[] a, int[] b, String name) {
    if (!Arrays.equals(a, b)) throw new AssertionError(name + ": " + Arrays.toString(a) + " != " + Arrays.toString(b));
    System.out.println("ok: " + name + " -> " + Arrays.toString(a));
  }
  public static void main(String[] a) {
    eq(CountingSort.countSort(new int[]{}), new int[]{}, "empty");
    eq(CountingSort.countSort(new int[]{4}), new int[]{4}, "single");
    eq(CountingSort.countSort(new int[]{-3,-1,-2,0,2,-5}), new int[]{-5,-3,-2,-1,0,2}, "negatives");
    eq(CountingSort.countSort(new int[]{5,5,5}), new int[]{5,5,5}, "duplicates");
    int[] in = {2,5,3,0,2,3,0,3}; int[] cp = in.clone();
    int[] out = CountingSort.countSort(in);
    int[] ref = in.clone(); Arrays.sort(ref);
    eq(out, ref, "matches Arrays.sort");
    eq(in, cp, "input unmodified");
    try { CountingSort.countSort(null); throw new AssertionError("expected NPE"); }
    catch (NullPointerException e) { System.out.println("ok: null throws NPE"); }
    System.out.println("ALL PASSED");
  }
}
